inline std::string physical(const char* filename) {
 const std::string_view path=filename?filename:"";
 constexpr std::string_view root="disc0:/PSP_GAME/SYSDIR/";
 if(path.substr(0,root.size())!=root)return std::string(path);
 const auto logical=path.substr(root.size());
 const auto found=std::lower_bound(std::begin(entries),std::end(entries),logical,
  [](const Entry& entry,std::string_view key){return entry.logical<key;});
 return found!=std::end(entries)&&found->logical==logical?found->physical:std::string(path);
}
